public class TournamentSelectorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        double[] fitness = {0.1, 0.9, 0.4, 0.7, 0.2, 0.55};

        try {
            check("select with a shared Random(1), size 2", 3,
                    TournamentSelector.select(fitness, 2, new java.util.Random(1L)));
            check("selectMany(size 2, seed 1, 10 rounds)", "[3, 1, 2, 2, 4, 1, 1, 4, 2, 5]",
                    java.util.Arrays.toString(TournamentSelector.selectMany(fitness, 2, 1L, 10)));
            check("selectMany(size 2, seed 7, 10 rounds)", "[2, 3, 4, 5, 0, 0, 1, 1, 3, 3]",
                    java.util.Arrays.toString(TournamentSelector.selectMany(fitness, 2, 7L, 10)));
            check("size 1 is plain uniform sampling", "[4, 2, 3, 4, 4, 4, 4, 5, 0, 0]",
                    java.util.Arrays.toString(TournamentSelector.selectMany(fitness, 1, 7L, 10)));
            check("a large tournament favours the fittest", "[3, 5, 1, 1, 3, 1, 5, 1, 3, 3]",
                    java.util.Arrays.toString(TournamentSelector.selectMany(fitness, 6, 7L, 10)));
            check("selectMany(size 3, seed 2024, 8 rounds)", "[2, 5, 5, 3, 1, 3, 3, 3]",
                    java.util.Arrays.toString(TournamentSelector.selectMany(fitness, 3, 2024L, 8)));
            check("a one-member population always wins", 0,
                    TournamentSelector.select(new double[]{5.0}, 4, new java.util.Random(3L)));
            check("the same seed replays the same tournaments",
                    java.util.Arrays.toString(TournamentSelector.selectMany(fitness, 2, 7L, 10)),
                    java.util.Arrays.toString(TournamentSelector.selectMany(fitness, 2, 7L, 10)));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

