/**
 * Tournament selection of parents from a population's fitness array.
 */
public class TournamentSelector {

    public static int select(double[] fitness, int tournamentSize, java.util.Random rng) {
        int best = -1;
        for (int t = 0; t < tournamentSize; t++) {
            int candidate = rng.nextInt(fitness.length);
            if (best == -1 || fitness[candidate] > fitness[best]) {
                best = candidate;
            }
        }
        return best;
    }

    public static int[] selectMany(double[] fitness, int tournamentSize, long seed, int count) {
        java.util.Random rng = new java.util.Random(seed);
        int[] winners = new int[count];
        for (int i = 0; i < count; i++) {
            winners[i] = select(fitness, tournamentSize, rng);
        }
        return winners;
    }
}
